SELECT COUNT(DISTINCT struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR)) AS "count_result" FROM triples t0, triples t1 WHERE t0.p = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#type' AND t0.o = struct_pack(kind := 0::UTINYINT, value := 'http://swat.cse.lehigh.edu/onto/univ-bench.owl#ResearchGroup', datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND struct_pack(kind := 0::UTINYINT, value := t1.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t1.p = 'http://swat.cse.lehigh.edu/onto/univ-bench.owl#subOrganizationOf' AND t1.o = struct_pack(kind := 0::UTINYINT, value := 'http://www.Department0.University0.edu', datatype := NULL::VARCHAR, lang := NULL::VARCHAR)